401: function Private.CancelAnimation(region, resetPos, resetAlpha, resetScale, resetRotation, resetColor, doOnFinished)
402:   local key = tostring(region);
403:   local anim = animations[key];
404: 
405:   if(anim) then
406:     if(resetPos) then
407:       if (anim.region.SetOffsetAnim) then
408:         anim.region:SetOffsetAnim(0, 0);
409:       else
410:         anim.region:ClearAllPoints();
411:         anim.region:SetPoint(anim.selfPoint, anim.anchor, anim.anchorPoint, anim.startX, anim.startY);
412:       end
413:     end
414:     if(resetAlpha) then
415:       if (anim.region.SetAnimAlpha) then
416:         anim.region:SetAnimAlpha(nil);
417:       else
418:         anim.region:SetAlpha(anim.startAlpha);
419:       end
420:     end
421:     if(resetScale) then
422:       if(anim.region.Scale) then
423:         anim.region:Scale(1, 1);
424:       else
425:         anim.region:SetWidth(anim.startWidth);
426:         anim.region:SetHeight(anim.startHeight);
427:       end
428:     end
429:     if(resetRotation and anim.region.SetAnimRotation) then
430:       anim.region:SetAnimRotation(nil)
431:     end
432:     if(resetColor and anim.region.ColorAnim) then
433:       anim.region:ColorAnim(nil);
434:     end
435: 
436:     animations[key] = nil;
437:     if(doOnFinished and anim.onFinished) then
438:       anim.onFinished();
439:     end
440:     return true;
441:   else
442:     return false;
443:   end
444: end
